(() => { const g = window.__game; const p = g.player; const V = p.position.constructor; const M4 = g.cam.camera.matrixWorld.constructor; const bad = [];
  for (const s of g.world.seats) {
    if (s.occupied) continue;
    g.travel('loggia'); sim(0.2);
    g.takeSeat(s); sim(1.0);
    const seated = !!p.seat;
    const seatY = new V().setFromMatrixPosition(s.frame(new M4())).y;
    g.interact(); sim(1.5);
    const drop = seatY - p.ctrl.position.y;
    const start = p.ctrl.position.clone(); let walk = 0;
    for (const yaw of [0, Math.PI / 2, Math.PI, -Math.PI / 2]) { p.ctrl.teleport(start.clone().add(new V(0, 0.02, 0)), 0); sim(0.1); g.cam.yaw = yaw; const b = p.ctrl.position.clone(); sim(0.8, ['KeyW']); walk = Math.max(walk, p.ctrl.position.distanceTo(b)); }
    const vehicle = ['driver', 'passenger', 'rower', 'boat'].includes(s.kind);
    if (!seated || walk < 0.5 || (!vehicle && (drop < 0.15 || drop > 1.3))) bad.push(`${s.id} (${s.kind}) seated=${seated} drop=${drop.toFixed(2)} walk=${walk.toFixed(2)}`);
  }
  return (bad.length ? 'FAIL ' : 'PASS ') + 'sit, stand up on the floor and walk away from every seat' + (bad.length ? ':\n  ' + bad.join('\n  ') : ''); })()
